let levelIndex=0;const K=1.25,CX=500,CY=165,NX=450,NY=190;const sc=(x,y)=>[NX+(x-CX)*K,NY+(y-CY)*K];const sp=(x,y,r=0,flip=1)=>{const q=sc(x,y);return{flip,r,x:q[0],y:q[1]}};const solution={L1:sp(380,45),L2:sp(380,165),M:sp(500,45),S1:sp(440,105),S2:sp(560,165),Q:sp(500,105),P:sp(380,45)};const starts={L1:[55,390],L2:[255,390],M:[505,400],S1:[520,545],S2:[645,545],Q:[520,645],P:[650,645]};let selected='L1',drag=null,tapStart=null;const pieces={};function pts(a){return a.map(p=>p.join(',')).join(' ')}function svgEl(tag,a={}){const n=document.createElementNS(NS,tag);Object.entries(a).forEach(([k,v])=>n.setAttribute(k,v));return n}function ensureBoard(){board.innerHTML='';const svg=svgEl('svg',{viewBox:'0 0 900 820',class:'classic-board','aria-label':'Tabuleiro do Tangram'});const rawTarget=levelIndex?extraLevels[levelIndex-1].target:[[620,45],[500,45],[380,45],[380,285],[620,285],[620,165]];const targetPts=rawTarget.map(v=>sc(v[0],v[1]));const target=svgEl('polygon',{points:pts(targetPts),class:'classic-target'});svg.appendChild(target);Object.entries(defs).forEach(([id,d])=>{const st=starts[id];pieces[id]={x:st[0],y:st[1],r:0,flip:1,snapped:false};const g=svgEl('g',{class:'classic-piece',id:'p-'+id,transform:`translate(${st[0]} ${st[1]}) scale(${K})`});const poly=svgEl('polygon',{points:pts(d.pts),fill:d.color,stroke:'#fff','stroke-width':3,'stroke-linejoin':'round'});const hit=svgEl('polygon',{points:pts(d.pts),fill:'transparent',stroke:'transparent','stroke-width':24,'pointer-events':'all'});g.append(poly,hit);svg.appendChild(g);g.addEventListener('pointerdown',e=>begin(e,id,g,svg));});board.appendChild(svg)}function select(id){selected=id;board.querySelectorAll('.classic-piece').forEach(x=>x.classList.toggle('selected',x.id==='p-'+id));status.textContent=defs[id].name+' selecionado.';updatePieceStudy()}function matrixPoint(e,svg){const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse())}function apply(id){const p=pieces[id],g=document.querySelector('#p-'+id);if(g)g.setAttribute('transform',`translate(${p.x} ${p.y}) rotate(${p.r}) scale(${p.flip*K} ${K})`)}function transformed(id){const p=pieces[id],a=p.r*Math.PI/180;return defs[id].pts.map(([x,y])=>{x*=p.flip*K;y*=K;return[p.x+x*Math.cos(a)-y*Math.sin(a),p.y+x*Math.sin(a)+y*Math.cos(a)]})}function anchors(movingId){
 const rawTarget=levelIndex?extraLevels[levelIndex-1].target:[[620,45],[500,45],[380,45],[380,285],[620,285],[620,165]];
 const aa=rawTarget.map(v=>sc(v[0],v[1]));
 const rawAtoms=levelIndex?extraLevels[levelIndex-1].atoms:classicAtoms;
 if(rawAtoms)Object.values(rawAtoms).forEach(poly=>poly.forEach(v=>aa.push(sc(v[0],v[1]))));
 Object.keys(defs).forEach(other=>{if(other!==movingId)transformed(other).forEach(v=>aa.push(v))});
 return aa
}function snap(id){
 const p=pieces[id],poly=transformed(id),aa=anchors(id);let best=null;
 poly.forEach(v=>aa.forEach(q=>{const dist=Math.hypot(v[0]-q[0],v[1]-q[1]);if(dist<14&&(!best||dist<best.d))best={d:dist,dx:q[0]-v[0],dy:q[1]-v[1]}}));
 if(best){p.x+=best.dx;p.y+=best.dy;apply(id);status.textContent='🧲 '+defs[id].name+' atraído ao encaixe.';return true}
 return false
}function signedArea(poly){let a=0;for(let i=0;i<poly.length;i++){const j=(i+1)%poly.length;a+=poly[i][0]*poly[j][1]-poly[j][0]*poly[i][1]}return a/2}
function polyArea(poly){return Math.abs(signedArea(poly))}
function ensureCCW(poly){return signedArea(poly)<0?[...poly].reverse():poly}
function clipConvex(subject,clipper){let output=subject.slice(),cp=ensureCCW(clipper.slice());function inside(p,a,b){return(b[0]-a[0])*(p[1]-a[1])-(b[1]-a[1])*(p[0]-a[0])>=-1e-7}function inter(s,e,a,b){const[x1,y1]=s,[x2,y2]=e,[x3,y3]=a,[x4,y4]=b,den=(x1-x2)*(y3-y4)-(y1-y2)*(x3-x4);if(Math.abs(den)<1e-10)return e;return[((x1*y2-y1*x2)*(x3-x4)-(x1-x2)*(x3*y4-y3*x4))/den,((x1*y2-y1*x2)*(y3-y4)-(y1-y2)*(x3*y4-y3*x4))/den]}
for(let j=0;j<cp.length;j++){const a=cp[j],b=cp[(j+1)%cp.length],inp=output.slice();output=[];if(!inp.length)break;let z=inp[inp.length-1];for(const e of inp){if(inside(e,a,b)){if(!inside(z,a,b))output.push(inter(z,e,a,b));output.push(e)}else if(inside(z,a,b))output.push(inter(z,e,a,b));z=e}}return output}
const classicAtoms={L1:[[380,45],[380,285],[500,165]],L2:[[380,285],[620,285],[500,165]],M:[[500,45],[620,45],[620,165]],S1:[[440,105],[560,105],[500,165]],S2:[[620,165],[620,285],[560,225]],Q:[[500,165],[560,105],[620,165],[560,225]],P:[[380,45],[500,45],[560,105],[440,105]]};
function geometryMetrics(){const rawAtoms=levelIndex?extraLevels[levelIndex-1].atoms:classicAtoms;if(!rawAtoms)return null;const atoms=Object.values(rawAtoms).map(poly=>poly.map(v=>sc(v[0],v[1]))),ids=Object.keys(defs),polys={};let outside=0,overlap=0;ids.forEach(id=>{polys[id]=ensureCCW(transformed(id));let insideArea=0;atoms.forEach(atom=>{const inter=clipConvex(polys[id],atom);if(inter.length>=3)insideArea+=polyArea(inter)});outside+=Math.max(0,polyArea(polys[id])-insideArea)});for(let i=0;i<ids.length;i++)for(let j=i+1;j<ids.length;j++){const inter=clipConvex(polys[ids[i]],polys[ids[j]]),a=inter.length>=3?polyArea(inter):0;if(a>1.25)overlap+=a}const area=57600*K*K,coverage=Math.max(0,Math.min(100,(area-outside-overlap)/area*100));return{coverage,outsidePct:outside/area*100,overlapPct:overlap/area*100}}
function begin(e,id,g,svg){e.preventDefault();select(id);g.setPointerCapture?.(e.pointerId);const q=matrixPoint(e,svg),p=pieces[id];p.snapped=false;g.classList.remove('snapped');tapStart={x:q.x,y:q.y,t:Date.now()};drag={id,g,svg,pid:e.pointerId,dx:q.x-p.x,dy:q.y-p.y,moved:false};g.addEventListener('pointermove',move);g.addEventListener('pointerup',end,{once:true})}
function move(e){if(!drag||e.pointerId!==drag.pid)return;e.preventDefault();const q=matrixPoint(e,drag.svg),p=pieces[drag.id];if(tapStart&&Math.hypot(q.x-tapStart.x,q.y-tapStart.y)>12)drag.moved=true;p.x=q.x-drag.dx;p.y=q.y-drag.dy;apply(drag.id)}
function end(e){if(!drag)return;drag.g.removeEventListener('pointermove',move);const id=drag.id,piece=pieces[id];if(!drag.moved&&tapStart&&Date.now()-tapStart.t<420){piece.r=(piece.r+45)%360;apply(id);snap(id);status.textContent=defs[id].name+' girado 45°.'}else{const magnet=snap(id);status.textContent=magnet?'🧲 Encaixe magnético. Ajuste se necessário.':'Peça posicionada. Ajuste se necessário.'}if(gamerActive&&gamerRunning&&drag.moved){gamerMoves++;if(gamerMoves%3===0){try{const gm=geometryMetrics(),mark=gm.coverage>=75?75:gm.coverage>=50?50:gm.coverage>=25?25:0;if(mark>gamerMilestone){gamerMilestone=mark;status.textContent='⚡ Speed Run · '+mark+'% da figura encaminhada.';try{navigator.vibrate?.(8)}catch(_){}}}catch(_){}}}drag=null;tapStart=null}
