 handle.onpointerdown=e=>{const r=mag.getBoundingClientRect();drag=true;dx=e.clientX-r.left;dy=e.clientY-r.top;handle.setPointerCapture?.(e.pointerId)};
 handle.onpointermove=e=>{if(!drag)return;const x=Math.max(8,Math.min(innerWidth-mag.offsetWidth-8,e.clientX-dx)),y=Math.max(72,Math.min(innerHeight-mag.offsetHeight-8,e.clientY-dy));mag.style.left=x+'px';mag.style.top=y+'px';mag.style.right='auto';choose(targetAt(x+mag.offsetWidth/2,y+28));localStorage.setItem('tangram2MagnifierPos',JSON.stringify({x:x/innerWidth,y:y/innerHeight}))};
