function lessonMakerPath(item){
 if(lessonSection!=='robotics')return '';
 const lessonText=((item?.id||'')+' '+(item?.topic||'')+' '+(item?.concept||'')).toLowerCase();
 const makerSuitable=/decompos|algorit|coorden|repet|padr|funç|recurs|geometr|javascript|jogo|array|engren|maquina|lego|equipe/.test(lessonText);
 if(!makerSuitable)return '';
 const y=Number(item?.year||lessonYear),id=item?.id||'';
 const isMechanics=/engren|maquinas|lego/i.test(id+' '+(item?.topic||'')+' '+(item?.title||''));
 const steps=isMechanics?[
  ['1','🔎','Observar','Identifique o mecanismo e diga o que você espera que aconteça.'],
  ['2','🧠','Prever','Antes de ligar o motor, preveja sentido, força e velocidade.'],
  ['3','🧱','Montar','Monte com LEGO Mindstorms mantendo eixos alinhados e peças organizadas.'],
  ['4','⚙️','Testar','Gire manualmente, depois motorize. Compare o resultado com a previsão.'],
  ['5','💻','Programar','Transforme o movimento desejado em comandos claros e ordenados.'],
  ['6','🧩','Resolver','Use o desafio visual para exercitar decomposição, rotação e estratégia.']
 ]:[
  ['1','🎯','Entender','Explique com suas palavras qual problema precisa ser resolvido.'],
  ['2','🧩','Decompor','Separe o problema em pequenas etapas que possam ser testadas.'],
  ['3','📝','Planejar','Organize a sequência antes de programar ou montar.'],
  ['4','🤖','Construir','Quando houver kit, monte e confira cada parte antes de avançar.'],
  ['5','💻','Programar','Digite, execute e corrija uma etapa de cada vez.'],
  ['6','🔷','Desafio visual','Aplique estratégia, orientação espacial e decomposição no Tangram.']
 ];
 return '<section class="maker-path" data-maker-path><div class="maker-path-head"><b>🛠 Da ideia à solução</b><small>'+(isMechanics?'Máquinas simples → LEGO Mindstorms → programação':'Pensamento computacional → construção → programação')+'</small></div><div class="maker-steps">'+steps.map(x=>'<div class="maker-step"><i>'+x[0]+'</i><span>'+x[1]+'</span><div><b>'+x[2]+'</b><small>'+x[3]+'</small></div></div>').join('')+'</div><button type="button" class="maker-tangram" data-lesson-tangram>🧩 Ir ao desafio Tangram</button><small class="maker-note">O desafio não substitui a montagem: ele treina a estratégia usada para dividir, orientar e resolver problemas.</small></section>';
}
