function lessonRaiConversationContext(item){
 const st=lessonRaiState(),id=item?.id||'',h=st[id]?.conversation||[];return h.slice(-3)
}
function lessonRaiFollowup(item,q){
 const h=lessonRaiConversationContext(item);if(!h.length)return '';
 const t=raiNorm(q),last=h[h.length-1];
 if(/ainda|nao entendi|mais simples|exemplo|outro exemplo/.test(t))return 'Vamos tentar de outro modo. '+(item?.example?('Use este exemplo da aula: '+item.example+' '):'')+'Pense em uma situação do cotidiano que tenha a mesma lógica. Qual seria o primeiro passo?';
 if(/isso|esse|essa|ele|ela|entao/.test(t)&&last?.answer)return 'Você está continuando a ideia anterior. Em resumo: '+String(last.answer).slice(0,220)+' Agora aplique essa ideia à sua nova pergunta: “'+String(q).slice(0,100)+'”.';
 return '';
}
const RAI_AI_URL='https://hfryzntefzjlqitpxbxw.supabase.co/functions/v1/rai-tutor-ai';
async function lessonRaiGenerative(item,q){
 try{
  const refs=lessonRaiKnowledge(item,q).slice(0,3).map(r=>({title:r.title||r.topic,concept:r.concept||r.objective||r.example}));
  const history=lessonRaiConversationContext(item).map(x=>({q:x.q,answer:x.answer}));
  const r=await fetch(RAI_AI_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,lesson:{year:item?.year||lessonYear,title:item?.title||item?.topic,objective:item?.objective,concept:item?.concept,example:item?.example,challenge:item?.challenge,learnerLevel:lessonRaiLearnerLevel(item,q)},references:refs,history})});
  if(!r.ok)return null;const d=await r.json();return d?.mode==='generative'&&d?.answer?String(d.answer).trim():null;
 }catch(_){return null}
}
