let uiFxCtx=null;
function uiFxTone(kind='tap'){const p=audioPrefs();if(!p.music&&!p.narration)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;if(!uiFxCtx)uiFxCtx=new AC();uiFxCtx.resume?.();const o=uiFxCtx.createOscillator(),g=uiFxCtx.createGain(),now=uiFxCtx.currentTime;const spec=kind==='primary'?[660,880,.075,.035]:kind==='hint'?[740,988,.09,.028]:kind==='danger'?[220,180,.08,.025]:[520,620,.045,.018];o.type='sine';o.frequency.setValueAtTime(spec[0],now);o.frequency.exponentialRampToValueAtTime(spec[1],now+spec[2]);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(spec[3],now+.012);g.gain.exponentialRampToValueAtTime(.0001,now+spec[2]);o.connect(g);g.connect(uiFxCtx.destination);o.start(now);o.stop(now+spec[2]+.02)}catch(_){}}
function uiFxKind(b){if(b.id==='next'||b.matches('.x1,.gamer,.aulas'))return'primary';if(b.matches('[data-action="hint"],[data-menu="rai"]'))return'hint';if(b.matches('[data-menu="reset"]'))return'danger';return'tap'}
document.addEventListener('pointerdown',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;b.classList.remove('ui-press');void b.offsetWidth;b.classList.add('ui-press');setTimeout(()=>b.classList.remove('ui-press'),240);try{if(!document.body.classList.contains('comfort-calm'))navigator.vibrate?.(uiFxKind(b)==='primary'?18:8)}catch(_){}uiFxTone(uiFxKind(b))},{passive:true});

let musicCtx=null,musicTimer=0,musicMode='study',musicStep=0,musicGain=null;
function musicStop(){clearInterval(musicTimer);musicTimer=0;if(musicGain){try{musicGain.gain.setTargetAtTime(0,musicCtx.currentTime,.08)}catch(_){}}}
function musicTone(freq,when,dur,vol,type='sine'){if(!musicCtx||!musicGain)return;const o=musicCtx.createOscillator(),g=musicCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(0,when);g.gain.linearRampToValueAtTime(vol,when+.03);g.gain.exponentialRampToValueAtTime(.0001,when+dur);o.connect(g);g.connect(musicGain);o.start(when);o.stop(when+dur+.05)}
function musicPhrase(){if(!musicCtx)return;const now=musicCtx.currentTime+.04,p=audioPrefs(),base=Math.max(.02,p.volume);if(musicMode==='gamer'){const seq=[220,277.18,329.63,440,329.63,277.18,246.94,329.63],f=seq[musicStep++%seq.length];musicTone(f,now,.18,.16,'triangle');musicTone(f/2,now,.32,.08,'sine')}else{const chords=[[261.63,329.63,392],[293.66,349.23,440],[246.94,329.63,392],[261.63,349.23,440]],ch=chords[musicStep++%chords.length];ch.forEach((f,i)=>musicTone(f,now+i*.18,1.35,.075,'sine'))}}
function musicStart(mode='study'){const p=audioPrefs();if(!p.music)return;musicMode=mode;if(!musicCtx){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;musicCtx=new AC();musicGain=musicCtx.createGain();musicGain.connect(musicCtx.destination)}musicCtx.resume?.();musicGain.gain.setTargetAtTime(Math.max(.015,p.volume*.32),musicCtx.currentTime,.12);clearInterval(musicTimer);musicPhrase();musicTimer=setInterval(musicPhrase,mode==='gamer'?360:1650)}
function musicDuck(on){if(musicGain&&musicCtx){const p=audioPrefs();musicGain.gain.setTargetAtTime(on?Math.max(.004,p.volume*.045):Math.max(.015,p.volume*.32),musicCtx.currentTime,.12)}}

function audioPrefs(){try{return {...{narration:true,music:false,volume:.18},...JSON.parse(localStorage.getItem(audioPrefsKey)||'{}')}}catch(e){return {narration:true,music:false,volume:.18}}}
function saveAudioPrefs(p){localStorage.setItem(audioPrefsKey,JSON.stringify(p))}
function speechMath(v){return String(v??'').replace(/≤/g,' menor ou igual a ').replace(/≥/g,' maior ou igual a ').replace(/≠/g,' diferente de ').replace(/≈/g,' aproximadamente igual a ').replace(/→/g,' leva a ').replace(/↔/g,' se relaciona com ').replace(/×/g,' vezes ').replace(/÷/g,' dividido por ').replace(/√/g,' raiz quadrada de ').replace(/π/g,' pi ').replace(/°/g,' graus ').replace(/%/g,' por cento ').replace(/\+/g,' mais ').replace(/=/g,' igual a ').replace(/</g,' menor que ').replace(/>/g,' maior que ').replace(/\^2\b/g,' ao quadrado ').replace(/\^3\b/g,' ao cubo ').replace(/\^/g,' elevado a ').replace(/\//g,' dividido por ').replace(/\s+/g,' ').trim()}
function lessonNarrationText(x){return speechMath([x.topic&&'Oi! Vamos aprender sobre '+x.topic+'.',x.objective&&'Hoje, nosso objetivo é '+x.objective,x.concept&&'Olha só: '+x.concept,x.example&&'Vamos a um exemplo. '+x.example,x.challenge&&'Agora é com você! '+x.challenge+' Pense com calma e tente resolver antes de ver a solução.'].filter(Boolean).join(' '))}
function narrateLesson(item,button){if(!('speechSynthesis'in window)){status.textContent='🔇 A narração não está disponível neste navegador.';return}const p=audioPrefs();if(!p.narration){status.textContent='🔇 Ative a narração em Áudio e narração.';return}speechSynthesis.cancel();document.querySelectorAll('[data-narrate]').forEach(b=>b.textContent='🔊 Ouvir aula');const u=new SpeechSynthesisUtterance(lessonNarrationText(item));u.lang='pt-BR';u.rate=.94;u.pitch=1;u.volume=1;const voices=speechSynthesis.getVoices(),v=voices.find(v=>/^pt-BR/i.test(v.lang))||voices.find(v=>/^pt/i.test(v.lang));if(v)u.voice=v;button.textContent='⏸ Narrando…';musicDuck(true);u.onend=u.onerror=()=>{button.textContent='🔊 Ouvir aula';musicDuck(false)};speechSynthesis.speak(u);t2event('lesson_narration',{year:String(lessonYear),section:lessonSection})}
function wireLessonAudio(m,items){m.querySelectorAll('[data-print-lesson]').forEach(b=>b.onclick=()=>{const d=b.closest('details');if(!d)return;const was=d.open;d.open=true;d.classList.add('lesson-print-target');if(!d.querySelector('.lesson-print-brand')){const brand=document.createElement('header');brand.className='lesson-print-brand';brand.innerHTML='<div class="lesson-print-logo" aria-label="Marca Tangram Educativo"><span>◢</span><span>◆</span><span>◣</span></div><div class="lesson-print-brandcopy"><strong>Tangram Educativo</strong><span>Prof. João Faustino Júnior</span><small>Plataforma educacional • Programação, Robótica e aprendizagem interdisciplinar</small></div>';d.insertBefore(brand,d.firstChild)}d.querySelectorAll('.lesson-full-print-only').forEach(el=>el.remove());const item=items[Number(b.dataset.printLesson)];if(item){const extra=document.createElement('section');extra.className='lesson-full-print-only';const rows=[['💡 Exemplo',item.example],['🧭 Representação',item.representation],['🌍 Aplicação',item.use],['⚠️ Atenção',item.observe],['✏️ Atividade guiada',item.guided]].filter(r=>r[1]);extra.innerHTML=rows.map(r=>'<div class="lesson-block"><b>'+lessonEsc(r[0])+'</b><p>'+lessonEsc(r[1])+'</p></div>').join('');const ch=d.querySelector('.lesson-challenge');(ch||d.querySelector('.lesson-reference'))?.before(extra)}d.querySelectorAll('.tea-step,[hidden]').forEach(el=>{el.dataset.printWasHidden=el.hidden?'1':'0';el.hidden=false;el.classList.add('print-show-all')});const printSheet=document.createElement('main');printSheet.id='lesson-print-sheet';const printClone=d.cloneNode(true);printClone.open=true;printSheet.appendChild(printClone);document.body.appendChild(printSheet);document.body.classList.add('printing-lesson');window.print();setTimeout(()=>{document.body.classList.remove('printing-lesson');printSheet.remove();d.classList.remove('lesson-print-target');d.querySelectorAll('.lesson-full-print-only').forEach(el=>el.remove());d.querySelectorAll('.print-show-all').forEach(el=>{if(el.dataset.printWasHidden==='1')el.hidden=true;delete el.dataset.printWasHidden;el.classList.remove('print-show-all')});d.open=was},350)});m.querySelectorAll('[data-narrate]').forEach(b=>b.onclick=()=>narrateLesson(items[Number(b.dataset.narrate)],b));m.querySelectorAll('[data-narrate-stop]').forEach(b=>b.onclick=()=>{speechSynthesis?.cancel();musicDuck(false);m.querySelectorAll('[data-narrate]').forEach(x=>x.textContent='🔊 Ouvir aula')})}
