function mosaicInit(){if(!mosaicLab)mosaicLab={mode:'build',selected:'red',placed:[],history:[]}}
function mosaicClone(){return mosaicLab.placed.map(p=>({...p}))} function mosaicPush(){mosaicLab.history.push(mosaicClone());if(mosaicLab.history.length>80)mosaicLab.history.shift()}
function mosaicCurrentTypes(){return mosaicLab?.super?superTypes:mosaicTypes}
function mosaicRemain(t){return mosaicCurrentTypes().find(x=>x.id===t).count-mosaicLab.placed.filter(p=>p.type===t).length}
function mosaicUnused(t){if(mosaicLab?.super){const z=superTypes.find(x=>x.id===t);return Array.from({length:mosaicRemain(t)},(_,i)=>({id:'super-'+t+'-'+i,type:t,x:0,y:0,w:z.w,h:z.h,clip:z.clip}))}return mosaicSlots.filter(s=>s.type===t&&!mosaicLab.placed.some(p=>p.slot===s.id))}
function mosaicPoint(ev){const b=document.querySelector('#mosaic-lab .mosaic-board'),r=b.getBoundingClientRect();return{x:Math.max(0,Math.min(100,(ev.clientX-r.left)/r.width*100)),y:Math.max(0,Math.min(100,(ev.clientY-r.top)/r.height*100))}}
function mosaicClamp(p,x,y){return{x:Math.max(0,Math.min(100-p.w,x)),y:Math.max(0,Math.min(100-p.h,y))}}
function openMosaicLab(k='build'){mosaicInit();mosaicMode=true;mosaicKey=k;if(k==='tangram'){document.querySelector('#mosaic-lab')?.classList.remove('show');document.querySelector('details:nth-of-type(2)')?.setAttribute('open','');document.querySelector('.classic-list')?.scrollIntoView({behavior:'smooth',block:'center'});status.textContent='🧩 Escolha um dos 14 desafios do Tangram.';return}let m=document.querySelector('#mosaic-lab');if(!m){m=document.createElement('div');m.id='mosaic-lab';m.className='mosaic-lab';m.innerHTML='<div class="mosaic-shell"><div class="mosaic-top"><div><b>▦ Laboratório de Mosaicos</b><small>Geometria modular · peças e modelo na mesma malha</small></div><button class="mosaic-expand">⛶</button><button class="mosaic-close">×</button></div><div class="mosaic-modes"><button data-mm="build">🧩 Montar</button><button data-mm="explore">✨ Explorar</button><button data-mm="symmetry">◐ Simetria</button><button data-mm="challenge">🎯 Resolver</button></div><p class="mosaic-instruction"></p><div class="mosaic-board"><div class="mosaic-axis"></div></div><div class="mosaic-palette"></div><div class="mosaic-actions"><button data-ma="undo">↶ Desfazer</button><button data-ma="mirror">⇆ Espelhar</button><button data-ma="model">👁 Modelo</button><button data-ma="restart">↻ Recomeçar</button><button data-ma="check">✓ Verificar</button></div><p class="mosaic-status"></p></div></div>';document.body.appendChild(m);m.querySelector('.mosaic-close').onclick=()=>m.classList.remove('show');m.querySelector('.mosaic-expand').onclick=()=>m.classList.toggle('expanded');m.querySelectorAll('[data-mm]').forEach(b=>b.onclick=()=>mosaicSetMode(b.dataset.mm));m.querySelectorAll('[data-ma]').forEach(b=>b.onclick=()=>mosaicAction(b.dataset.ma));m.querySelector('.mosaic-board').onclick=e=>{if(e.target===e.currentTarget||e.target.classList.contains('mosaic-axis'))mosaicPlace(e)}}m.classList.add('show');if(k==='super'){m.classList.add('super-mosaic');mosaicLab={mode:'explore',selected:'tri',placed:[],history:[],super:true};mosaicSetMode('explore');m.querySelector('.mosaic-instruction').textContent='Super Mosaico · 36 peças: combine quadrados, triângulos, paralelogramos e trapézios.'}else{m.classList.remove('super-mosaic');mosaicSetMode(k==='symmetry'?'symmetry':k==='free'?'explore':k==='geometry'?'challenge':'build')}}
function mosaicSetMode(mode){mosaicInit();mosaicLab.mode=mode;const m=document.querySelector('#mosaic-lab');m.classList.toggle('symmetry',mode==='symmetry');m.querySelectorAll('[data-mm]').forEach(b=>b.classList.toggle('on',b.dataset.mm===mode));const x={build:'Monte o modelo: cada peça nasce com a dimensão correta da malha.',explore:'Explore livremente. A peça mantém exatamente o tamanho geométrico de origem.',symmetry:'Crie de um lado e reproduza do outro lado do eixo.',challenge:'Resolva usando as mesmas 20 peças e as proporções do modelo.'};m.querySelector('.mosaic-instruction').textContent=x[mode];mosaicRender()}
function mosaicRender(){mosaicInit();const m=document.querySelector('#mosaic-lab'),pal=m.querySelector('.mosaic-palette'),b=m.querySelector('.mosaic-board');pal.innerHTML=mosaicCurrentTypes().map(t=>{const s=mosaicLab.super?t:mosaicSlots.find(x=>x.type===t.id);return '<button data-mt="'+t.id+'" class="'+(mosaicLab.selected===t.id?'on':'')+'"><i style="background:'+t.color+';clip-path:'+s.clip+'"></i><span>'+t.name.replace(/ .*/,'')+'</span><b>×'+mosaicRemain(t.id)+'</b></button>'}).join('');pal.querySelectorAll('[data-mt]').forEach(x=>x.onclick=()=>{mosaicLab.selected=x.dataset.mt;mosaicRender()});b.querySelectorAll('.mosaic-piece').forEach(x=>x.remove());mosaicLab.placed.forEach(p=>{const t=mosaicCurrentTypes().find(x=>x.id===p.type),el=document.createElement('div');el.className='mosaic-piece';el.dataset.id=p.id;el.style.cssText='left:'+p.x+'%;top:'+p.y+'%;width:'+p.w+'%;height:'+p.h+'%;background:'+t.color+';clip-path:'+p.clip+';transform:rotate('+(p.r||0)+'deg) scaleX('+(p.flip||1)+')';el.onpointerdown=ev=>mosaicStartDrag(ev,p,el);el.ondblclick=ev=>{ev.stopPropagation();mosaicPush();p.r=((p.r||0)+90)%360;mosaicRender()};b.appendChild(el)});m.querySelector('.mosaic-status').textContent=mosaicLab.placed.length+' / 20 peças usadas'}
function mosaicPlace(ev){mosaicInit();const type=mosaicLab.selected,unused=mosaicUnused(type);if(!unused.length)return;const pt=mosaicPoint(ev);let s=unused[0];if(mosaicLab.super){s=unused[0]}else if(mosaicLab.mode==='build'){s=unused.reduce((a,z)=>Math.hypot(z.x+z.w/2-pt.x,z.y+z.h/2-pt.y)<Math.hypot(a.x+a.w/2-pt.x,a.y+a.h/2-pt.y)?z:a,s)}mosaicPush();let p={id:Date.now()+Math.random(),type,slot:s.id,x:s.x,y:s.y,w:s.w,h:s.h,clip:s.clip,r:0,flip:1};if(mosaicLab.mode!=='build'||mosaicLab.super){const q=mosaicClamp(p,pt.x-p.w/2,pt.y-p.h/2);p.x=q.x;p.y=q.y}mosaicLab.placed.push(p);mosaicRender()}
function mosaicMagnet(p){const step=25,threshold=3.2;let nx=Math.round(p.x/step)*step,ny=Math.round(p.y/step)*step,snapped=false;if(Math.abs(nx-p.x)<=threshold){p.x=nx;snapped=true}if(Math.abs(ny-p.y)<=threshold){p.y=ny;snapped=true}const edges=[0,25,50,75,100];edges.forEach(v=>{if(Math.abs(p.x-v)<=threshold){p.x=v;snapped=true}if(Math.abs((p.x+p.w)-v)<=threshold){p.x=v-p.w;snapped=true}if(Math.abs(p.y-v)<=threshold){p.y=v;snapped=true}if(Math.abs((p.y+p.h)-v)<=threshold){p.y=v-p.h;snapped=true}});const q=mosaicClamp(p,p.x,p.y);p.x=q.x;p.y=q.y;return snapped}
