function mosaicAction(a){mosaicInit();if(a==='undo'){if(mosaicLab.history.length)mosaicLab.placed=mosaicLab.history.pop();mosaicRender();return}if(a==='restart'){if(mosaicLab.placed.length)mosaicPush();mosaicLab.placed=[];mosaicRender();return}if(a==='mirror'){const p=mosaicLab.placed[mosaicLab.placed.length-1];if(!p){document.querySelector('#mosaic-lab .mosaic-status').textContent='Selecione ou coloque uma peça para espelhar.';return}mosaicPush();p.flip=(p.flip||1)*-1;mosaicRender();document.querySelector('#mosaic-lab .mosaic-status').textContent='⇆ Última peça espelhada.';return}if(a==='model'){mosaicShowModel();return}if(a==='check'){const m=document.querySelector('#mosaic-lab');if(mosaicLab.super){const n=mosaicLab.placed.length;m.querySelector('.mosaic-status').textContent=n<12?'Comece o padrão: use repetição, rotação ou simetria.':n<36?'Super Mosaico · '+n+' / 36 peças. Continue ou crie uma composição menor.':'🏆 Super Mosaico completo com 36 peças! Agora tente outra montagem.';if(n===36)localStorage.setItem('tangram2SuperMosaic','1');return}if(mosaicLab.mode==='build'){let ok=0;mosaicLab.placed.forEach(p=>{const s=mosaicSlots.find(x=>x.id===p.slot);if(s&&Math.abs(p.x-s.x)<3&&Math.abs(p.y-s.y)<3)ok++});m.querySelector('.mosaic-status').textContent=ok===20?'🏆 Modelo completo! As 20 peças ocupam a malha corretamente.':'🧩 '+ok+' / 20 peças estão em seus encaixes do modelo.';return}m.querySelector('.mosaic-status').textContent=mosaicLab.placed.length===20?'🏆 Composição completa. Experimente uma nova organização.':'Use as peças disponíveis para completar a composição.'}}
