// v2.0.93 - diario pedagogico local e relatorio de desempenho
const learningKey='tangram2LearningLog';
function learningLog(){try{return JSON.parse(localStorage.getItem(learningKey)||'[]')}catch(e){return []}}
function learningSave(x){localStorage.setItem(learningKey,JSON.stringify(x.slice(-500)))}
function learningLevelName(){return levelIndex===0?'Quadrado Clássico':(extraLevels[levelIndex-1]?.name||('Desafio '+(levelIndex+1)))}
function recordLearningAttempt(){const x=learningLog();x.push({type:'attempt',level:levelIndex+1,name:learningLevelName(),at:Date.now(),gamer:!!gamerActive});learningSave(x)}
function recordLearningSuccess(){const x=learningLog();x.push({type:'success',level:levelIndex+1,name:learningLevelName(),at:Date.now(),gamer:!!gamerActive});learningSave(x)}
function learningReport(){
 const x=learningLog(),by={};x.forEach(r=>{const k=r.level||0;if(!by[k])by[k]={name:r.name||('Desafio '+k),attempts:0,success:0,last:0};if(r.type==='attempt')by[k].attempts++;if(r.type==='success')by[k].success++;by[k].last=Math.max(by[k].last,r.at||0)});
 return {rows:Object.entries(by).sort((a,b)=>+a[0]-+b[0]).map(([level,v])=>({level:+level,...v})),attempts:x.filter(r=>r.type==='attempt').length,success:x.filter(r=>r.type==='success').length,first:x[0]?.at||0,last:x[x.length-1]?.at||0}
}

